export const categories = [
  { id: 'colors', slug: 'color-screens', label: 'Color screens', short: 'Colors', icon: 'palette', description: 'A clean canvas in every color. Open a full screen background or download a precisely sized PNG.', intro: 'Solid colors remove the distractions of a desktop or photograph. Use white for a quick light source, black to inspect bright pixels, or red, green, and blue to look at individual color channels. Each screen includes a color picker, visual dimming, full screen mode, and a PNG background generator. These are visual tools, not automatic panel diagnostics or professional calibration equipment.' },
  { id: 'tests', slug: 'screen-tests', label: 'Screen tests', short: 'Screen tests', icon: 'monitor', description: 'Get a closer look at your display with simple, controlled patterns.', intro: 'A photograph can hide display defects behind its detail. Flat colors, grayscale steps, and smooth gradients are easier to inspect. Start at your monitor’s native resolution and normal viewing position, then use the tests below. A browser cannot certify a display or repair a physical pixel; it can provide repeatable patterns so you can make a more informed visual check.' },
  { id: 'lighting', slug: 'lighting-tools', label: 'Lighting tools', short: 'Lighting', icon: 'sun', description: 'A softer light for your next call, portrait, or late-night creative session.', intro: 'Turn the display you already have into a small, adjustable fill light. Choose a full panel for broad light or a ring-shaped pattern with a dark center. Start at a comfortable brightness and compare the result in your camera application. These tools do not turn on your camera or control the hardware brightness of your monitor.' },
  { id: 'savers', slug: 'screensavers', label: 'Screensavers', short: 'Screensavers', icon: 'clock', description: 'Make your idle screen a little quieter, or a little more playful.', intro: 'Give your screen one job: show the time, count down a focused session, or play a gentle animation. The tools below run inside a browser tab and can expand to full screen. They are not operating system screensavers, so they cannot lock your device or guarantee that its display will stay awake.' },
  { id: 'extras', slug: 'screen-demos', label: 'Screen demos', short: 'Demos', icon: 'sparkles', description: 'Clearly labeled visual simulations for a set, a sketch, or a harmless demonstration.', intro: 'Create a fictional update screen or a stylized cracked-display effect. Every demo keeps a visible simulation label and an exit control. Nothing is installed, no files are scanned, and no update or hardware damage takes place. Use these effects with the device owner’s permission and avoid interrupting anyone’s work.' },
];

const colorDefinitions = [
  ['white-screen','White screen','#FFFFFF','A bright, blank canvas for a little extra light, a quick display check, or your next creative project.',
   'A white screen fills your display with an even white background. It can be useful when you need a simple fill light, an uncluttered tracing surface, or a bright field for finding dark marks on a monitor. Open the canvas in full screen to remove the surrounding controls.',
   [['A soft light for video calls','Place the display slightly behind your webcam and open a white screen. Start with a low brightness, look at the camera preview, and increase it only as needed. The screen can add fill light to shadows; its effect depends on the size and brightness of your display.'],['A clearer display check','A white background makes dark pixels and some uneven areas easier to see. Clean away surface dust first, then compare the same spot on black, red, green, and blue. Use the [[/dead-pixel-test/|dead pixel test]] to step through those backgrounds without repeatedly changing pages.'],['A simple creative background','Download a white PNG at the dimensions of your presentation, video, or design file. A digital background has exact pixel dimensions, but the physical light coming from your screen depends on its settings. For paper tracing, use a light touch and avoid pressing against the panel.']],
   'Pure white is RGB 255, 255, 255. The on-page brightness slider adds visual dimming; it does not move the brightness setting in your operating system. For a warmer alternative, try the [[/zoom-light/|video call light]] or a [[/yellow-screen/|yellow screen]].'],
  ['black-screen','Black screen','#000000','A full screen black background for bright-pixel checks, dark backdrops, and fewer distractions.',
   'A black screen removes image detail and displays a uniform dark field. This can make bright or stuck pixels stand out and help you notice reflections. It also creates a quiet background on a second monitor while you work elsewhere.',
   [['Look for bright points','View the black canvas in a dim room and scan the display in sections. A tiny bright point may be a stuck pixel, dust reflecting a light, or another artifact. Compare it against the [[/white-screen/|white screen]] before drawing a conclusion.'],['Inspect dark-scene uniformity','Sit directly in front of your screen and look for obvious patches. Room reflections, viewing angle, and panel technology can affect what you see. This browser pattern is a useful comparison surface rather than a measurement of contrast or black level.'],['Create a dark digital backdrop','Download a black PNG for a slide, an edit, or an image composition. The file contains black pixels even if your monitor appears gray in a bright room. An LCD backlight may stay on while displaying black.']],
   'Black content is not the same as turning off your monitor. Power use varies by panel type and settings, and this page cannot lock your computer. Use your operating system’s lock or display controls when you step away.'],
  ['red-screen','Red screen','#FF0000','A pure red background for color-channel inspection and bold digital backdrops.',
   'This canvas displays RGB red across the selected area. An isolated red field is useful when a mixed image makes small display differences hard to locate. It is also an easy way to create a consistent red background for a creative project.',
   [['Inspect the red channel','Open full screen and look for dots or lines that differ from the surrounding red. Repeat on [[/green-screen/|green]] and [[/blue-screen/|blue]] so you can compare the same location across three color channels.'],['Match a visual backdrop','Use the hex field to replace the default red with your project’s exact code. Download the PNG at your required resolution and import it into your editor. The RGB values stay consistent even though screens can reproduce them differently.'],['Make comparisons repeatable','Keep the same viewing angle and hardware brightness when comparing displays. Turn off automatic color changes if you want a more consistent visual comparison, and record the settings you used.']],
   'A bright red background can look intense in a dark room. Reduce the display’s brightness to a comfortable level. A browser color screen cannot determine color accuracy or fix a defective subpixel.'],
  ['green-screen','Green screen','#00FF00','A solid green background for channel checks, compositing practice, and exact-size downloads.',
   'A digital green screen fills your display with one uniform green color. You can inspect green-channel behavior or create a background file for an editing workflow. A monitor showing green is different from a physical chroma-key backdrop behind a subject.',
   [['Check green-channel consistency','Scan the panel for points that look darker, brighter, or differently colored. Compare suspicious areas on the [[/red-screen/|red screen]] and [[/blue-screen/|blue screen]] before assuming the panel is defective.'],['Practice a chroma-key workflow','Download a green PNG and use it in a compositing exercise. Green reflected from an actual screen can spill onto nearby objects, so a display is not a substitute for a properly lit physical backdrop.'],['Export a precise green','Change the hex value if your editor expects a specific green. Set the width and height to your project dimensions. PNG export does not add text, controls, or the surrounding page.']],
   'Use a [[/custom-color-screen/|custom color screen]] when you need a different keying color. If you are inspecting hardware, our [[/dead-pixel-test/|manual pixel test]] provides a guided color sequence.'],
  ['blue-screen','Blue screen','#0000FF','An uninterrupted blue field for visual inspection, compositing, or a clean blue background.',
   'This is a plain blue color tool, not a system error message. It can help you inspect one display channel at a time and gives you a quick way to create a blue image with exact dimensions.',
   [['Inspect one color at a time','Look across the blue field at normal brightness. If a point appears unusual, repeat the check using [[/red-screen/|red]] and [[/green-screen/|green]]. Looking at the same position across colors is more useful than a single screenshot.'],['Build a blue graphic background','Enter a different hex value to match your palette, then download a PNG. For artwork, use the exported RGB values as your reference; visual appearance alone changes with display settings and ambient light.'],['Compare surfaces and reflections','An even field can reveal reflections or surface marks that detailed wallpaper hides. Change your viewing position slightly to distinguish a reflection from a point that stays fixed within the panel.']],
   'The tool does not scan your device or identify a hardware fault automatically. For a broader check that includes grayscale and gradients, open the [[/monitor-test/|monitor test]].'],
  ['yellow-screen','Yellow screen','#FFE45C','A sunny yellow canvas for warm-toned fill light and simple background design.',
   'A yellow screen creates a warmer-looking alternative to pure white. Use it as a creative color field or experiment with the tone of a small fill light. Its effect in a camera depends on white balance, exposure, and the other light sources in the room.',
   [['Add a warm accent','Place a yellow screen near an object to explore a warm accent in a photo. Keep the display outside the frame when possible, and use a camera preview to judge reflections and color spill.'],['Create presentation backgrounds','Download a yellow PNG in a slide or video format. If you plan to place text on it, choose a dark foreground and check readability in your actual design. A solid color is a backdrop, not a finished accessible layout.'],['Compare warm tones','Switch between yellow and [[/orange-screen/|orange]] while keeping screen brightness unchanged. For a more restrained warm light with adjustable color, try the [[/zoom-light/|video call lighting tool]].']],
   'Yellow content does not change the physical color temperature of your panel or provide an eye-health benefit. Use a comfortable brightness and take breaks as you normally would.'],
  ['orange-screen','Orange screen','#FF9B54','A warm orange background for creative lighting, mood boards, and digital canvases.',
   'An orange screen adds a warm color field without image detail. It works as a bold design reference or a small accent light for a subject near your display. The default is a warm creative orange; you can enter a different hex value at any time.',
   [['Experiment with accent lighting','Aim an orange screen toward one side of a small object and use a neutral light on the other side. A display has limited output, so keep expectations modest and inspect the camera preview.'],['Make a warm background asset','Choose your export dimensions and save a clean PNG. You can bring that image into a social graphic or video timeline without cropping away the site’s controls.'],['Build a balanced palette','Compare orange with a [[/blue-screen/|blue background]] as a creative starting point. Test the final colors in your design instead of assuming that a pleasing pair will provide enough text contrast.']],
   'For a smooth transition between warm and cool tones, use the [[/gradient-screen/|gradient screen]]. Visual dimming changes the displayed color output, not your device’s hardware settings.'],
  ['pink-screen','Pink screen','#FFB8D9','A soft pink canvas for playful backdrops, gentle accent light, and color experiments.',
   'This pink screen is a simple pastel color field with no image, texture, or logo inside the exported background. Use it for an uncomplicated design layer or a small amount of colored light near your display.',
   [['Create a pastel canvas','Download a pink PNG at the exact size of your artboard. Add your typography and imagery in your editor so you can control spacing and readability rather than treating the color file as a complete design.'],['Try a subtle light accent','A pink screen can add a gentle tint to nearby objects. Watch for unintended color on skin or reflective packaging. Use the [[/white-screen/|white screen]] when you want a more neutral starting point.'],['Explore complementary tones','Compare pink with [[/purple-screen/|purple]] or a [[/cyan-screen/|cyan background]]. The custom picker lets you keep a chosen hex value consistent across exported files.']],
   'A pastel screen is not a calibrated color reference. For printed work, use an appropriate color-managed workflow and a proof from your print provider.'],
  ['purple-screen','Purple screen','#A78BFA','An even purple background for atmospheric accents and digital design assets.',
   'A purple screen turns the display into a single field of violet-toned color. Choose it for an ambient accent or a plain design layer, then adjust the shade to suit your project.',
   [['Add atmosphere to a small scene','Place the display near the subject and keep another light available for detail. Purple light can shift skin and fabric colors, so compare the effect with and without the screen in your camera application.'],['Create matching digital assets','Use the hex field to match an existing brand palette. Export at the target dimensions to avoid stretching the finished image inside a layout.'],['Inspect color differences','A uniform purple field can make large patches easier to spot, but it mixes red and blue channels. Use the separate [[/red-screen/|red]] and [[/blue-screen/|blue]] tests for a clearer channel comparison.']],
   'For a two-color backdrop, create a blend in the [[/gradient-screen/|gradient tool]]. This page displays a chosen color; it does not assess monitor gamut or professional color accuracy.'],
  ['cyan-screen','Cyan screen','#58D8E7','A cool cyan background for clean digital canvases and color-channel comparisons.',
   'Cyan combines green and blue in the RGB color model. This screen gives you an uncluttered cool backdrop and an additional comparison field when checking your display visually.',
   [['Compare mixed-channel output','After inspecting [[/green-screen/|green]] and [[/blue-screen/|blue]] separately, a cyan field offers another view of the same panel. Compare the same locations while keeping your viewing position fixed.'],['Make a fresh graphic backdrop','Export a clean cyan PNG for your editor. Choose the target size before downloading so the image drops straight into your slide, thumbnail, or video project.'],['Try a cool accent','A cyan screen can add a cool reflection to a small object. Move it until the reflection looks deliberate and avoid using the display as your only light if you need accurate product colors.']],
   'For a neutral comparison after a colorful screen, open [[/gray-screen/|gray]] or [[/white-screen/|white]]. Your visual adaptation can change how the next background appears.'],
  ['gray-screen','Gray screen','#808080','A neutral gray background for visual comparisons and distraction-free digital space.',
   'A middle-gray canvas is a useful neutral starting point between pure white and black. It can make uneven areas easier to notice without the intensity of a bright white screen, and it provides a simple background for layout work.',
   [['Inspect broad uniformity','View the gray field straight on and look for obvious bright or dark regions. Move your head gently to see how much of the appearance comes from viewing angle. A visual impression is not a measured uniformity score.'],['Compare without saturated color','Return to a gray screen between strongly colored backgrounds. It gives you a neutral reference surface, although it cannot guarantee that your eyes or display have returned to a calibrated state.'],['Create a plain workspace backdrop','Download a gray PNG at your preferred desktop or slide size. If you need a lighter or darker shade, use the custom picker instead of changing the display’s hardware brightness.']],
   'Middle gray in an RGB file is not a substitute for a photographic gray card. For near-black and near-white steps, open the [[/monitor-test/|monitor test]] and choose its contrast pattern.'],
];

export const tools = colorDefinitions.map(([slug,name,color,description,intro,uses,note]) => ({slug,name,color,description,intro,uses:uses.map(([title,text])=>({title,text})),note,category:'colors',kind:'solid', guide: slug==='white-screen' ? 'use-a-white-screen' : 'check-your-monitor'}));

const extras = [
  {slug:'custom-color-screen',name:'Custom color screen',color:'#C9DEAA',category:'colors',kind:'solid',description:'Your exact color, edge to edge. Pick a shade, enter a hex code, and make it yours.',intro:'Create a full screen background from any six-digit RGB hex color. The picker and text field stay in sync, and the PNG generator exports the selected color without interface controls. This is useful for matching a digital palette, building a slide background, or choosing a consistent color field for a display comparison.',uses:[{title:'Choose a repeatable color',text:'Type a six-digit value such as #C9DEAA or use the native color picker. An exact code is easier to share with a collaborator than a description like “a slightly warmer green.” The display may still look different across devices.'},{title:'Create the right file size',text:'Choose Full HD, QHD, 4K, a portrait format, or your own dimensions. The generated PNG is a solid image, so its file size is usually small even at a high resolution. Export is limited to 4,096 pixels per edge to avoid excessive browser memory use.'},{title:'Compare flat colors',text:'Use the related [[/color-screens/|color screen collection]] for common presets. For a gradual transition between shades, the [[/gradient-screen/|gradient screen]] provides two colors and an adjustable angle.'}],note:'A hex code describes an RGB color, not a measured physical light output. Color profiles, panel settings, and ambient light still influence what you see.',guide:'choose-a-background-size'},
  {slug:'dead-pixel-test',name:'Dead pixel test',color:'#66C29A',category:'tests',kind:'pixels',description:'Inspect your display one color at a time. A simple, manual check for pixels that stand out.',intro:'This manual dead pixel test cycles through white, black, red, green, and blue. Each flat background removes visual detail so an unusual point is easier to spot. The test does not access your display hardware, count defective pixels, or claim to repair them.',uses:[{title:'Set up a fair visual check',text:'Use the panel’s native resolution, clean away surface dust, and choose a comfortable brightness. Sit directly in front of the screen. Start with white, then advance using the Next color button, arrow keys, or Space while full screen.'},{title:'Compare the same location',text:'If you find a suspicious dot, keep track of its position and look at it on every color. A black dot on white is not enough to diagnose the cause. Dust, image scaling, and surface damage can resemble a pixel defect.'},{title:'Keep your conclusion practical',text:'A point that remains unusual across multiple fields may deserve closer inspection. Record its position and consult the manufacturer’s support or warranty guidance. Read the [[/guides/check-your-monitor/|monitor inspection guide]] for a repeatable checklist.'}],note:'There is no rapid flashing or “pixel repair” routine. The optional auto-cycle changes color every three seconds and can be paused at any time.',guide:'check-your-monitor'},
  {slug:'monitor-test',name:'Monitor test',color:'#DDE5EF',category:'tests',kind:'monitor',description:'Grayscale, gradients, and a crisp grid. Give your display a thoughtful visual check.',intro:'The monitor test brings three controlled patterns into one place: a grayscale ramp, near-black and near-white steps, and a geometric grid. These patterns help you inspect visible banding, clipped detail, and shape consistency without the distraction of a photograph.',uses:[{title:'Look for visible banding',text:'Choose Gradient and inspect the smooth transition from black to white. Noticeable steps can come from the panel, color settings, browser rendering, or the signal path. A browser gradient cannot identify the exact cause by itself.'},{title:'Compare shadow and highlight detail',text:'Choose Contrast steps. Try to distinguish adjacent dark patches and adjacent light patches from your normal viewing position. Keep the display comfortable; increasing brightness to an extreme can make another part of the pattern harder to judge.'},{title:'Inspect geometry',text:'Choose Grid and check whether squares look even and straight. Use your display’s native resolution and avoid browser zoom when comparing patterns. For isolated points, follow up with the [[/dead-pixel-test/|dead pixel test]].'}],note:'This is a visual inspection aid, not a calibration instrument. It does not measure color gamut, refresh rate, response time, HDR performance, or brightness in nits.',guide:'check-your-monitor'},
  {slug:'gradient-screen',name:'Gradient screen',color:'#D9D6FA',category:'tests',kind:'gradient',description:'Two colors, one smooth canvas. Build a gradient or inspect how your display handles a blend.',intro:'Create a full screen linear gradient with two custom colors and an adjustable angle. Use it as a digital backdrop, a soft visual field, or a quick way to look for visible steps in a transition. A PNG download includes the gradient at your chosen dimensions.',uses:[{title:'Make a gentle background',text:'Choose two nearby shades for a quiet blend or two different hues for a bolder effect. Rotate the angle until the transition fits your composition. Download at the dimensions of your project to keep the result predictable.'},{title:'Inspect a smooth transition',text:'Try black and white, then look for abrupt bands. What you see depends on the full display pipeline, including rendering and panel settings. This test alone does not measure the panel’s bit depth.'},{title:'Pair with simpler tests',text:'A smooth gradient is easier to interpret after checking flat [[/color-screens/|color backgrounds]]. Use the [[/monitor-test/|monitor test]] for grayscale steps and grid geometry in the same session.'}],note:'The background is static. It does not flash, animate, or adjust your operating system’s color profile.',guide:'check-your-monitor'},
  {slug:'zoom-light',name:'Video call light',color:'#FFF4DF',category:'lighting',kind:'light',description:'Better light, with the screen you already have. A simple fill light for your next video call.',intro:'Turn your display into a broad light source beside your camera. Choose a neutral or warm tone and adjust the visual brightness while checking your appearance in your video-call application. The tool does not need camera access and has no connection to any particular meeting platform.',uses:[{title:'Position the screen first',text:'Place the bright area slightly above or beside your camera, facing you. If you use a second monitor, keep this page there and your call on the other display. Distance and angle can matter more than choosing a very bright setting.'},{title:'Balance the room light',text:'Start low and bring up the fill gradually. A screen will not overpower a bright window behind you. Face the room’s main light when possible, then use the display to soften remaining shadows.'},{title:'Keep skin tones natural',text:'Choose neutral white as a starting point. If the room is warm, a slightly warmer screen may blend better. Compare the result in your camera preview instead of assuming the on-page color will look identical on camera.'}],note:'For a dark center and adjustable luminous border, try the [[/ring-light/|ring light]]. For a practical setup checklist, read our [[/guides/better-video-call-lighting/|video call lighting guide]].',guide:'better-video-call-lighting'},
  {slug:'ring-light',name:'Ring light',color:'#FFF1DB',category:'lighting',kind:'ring',description:'A luminous border, a quiet center. Adjust the size and warmth of your on-screen ring light.',intro:'This ring light draws a bright oval around a dark center. It offers a different light pattern from a fully white display and can be useful when your screen sits close to your camera. Ring size, color, and visual brightness are adjustable.',uses:[{title:'Set the ring width',text:'Move the Ring width slider to change how much of the display emits light. A wider ring creates a larger bright area; a narrow ring produces less total light. Use your call’s preview to choose a setting that looks comfortable.'},{title:'Place the display near eye level',text:'Raise the display or adjust your seat so the light comes from a useful angle. The dark center is part of the pattern, not a window for another application. The page does not display or record your webcam.'},{title:'Try a full-panel alternative',text:'If the ring does not add enough light, use the [[/zoom-light/|video call light]] to illuminate the full canvas. A screen’s output depends on hardware brightness, screen size, distance, and room lighting.'}],note:'An on-screen ring is not equivalent to a dedicated photographic ring light. If you wear glasses, adjust the display angle to reduce distracting reflections.',guide:'better-video-call-lighting'},
  {slug:'clock-screensaver',name:'Clock screensaver',color:'#1F2522',category:'savers',kind:'clock',description:'Just the time. A calm, full screen clock for your desk, workspace, or second monitor.',intro:'Keep the current time in view with a minimal digital clock. The display uses your device’s local time and updates while the tab is active. Choose a 12-hour or 24-hour format and open it in full screen for a quiet desk display.',uses:[{title:'Choose a readable format',text:'Switch between 12-hour and 24-hour time, then move the screen to a position you can glance at comfortably. The time comes from your device, so correct its system clock if the display appears inaccurate.'},{title:'Use a second display',text:'Keep the clock on another monitor while you work on the main one. The optional Keep screen awake control requests a browser wake lock when supported. System power settings and browser behavior may still interrupt it.'},{title:'Protect your work session',text:'This page cannot lock your computer or hide sensitive applications securely. Use your operating system’s lock screen when leaving your desk. If you want a timed session instead, open the [[/focus-timer/|focus timer]].'}],note:'The clock is a browser display, not an alarm service or a system screensaver. There is no sound or notification when you switch away.',guide:'fullscreen-and-shortcuts'},
  {slug:'bouncing-logo',name:'Bouncing screensaver',color:'#18231E',category:'savers',kind:'bounce',description:'A small nod to the classics. Watch a simple shape bounce around your screen.',intro:'A minimal moving mark travels around the canvas and rebounds at its edges. Change the speed or pause the animation when you like. This is an original browser animation rather than a reproduction of a device manufacturer’s screensaver or logo.',uses:[{title:'Choose a gentle pace',text:'Start with a slower animation speed if the canvas is in your peripheral vision. Pause the movement at any time with the control beside the preview. The page respects reduced-motion preferences by starting paused.'},{title:'Expand the canvas',text:'Open full screen to give the shape more room. Your browser may display a temporary notification explaining how to exit. Escape returns to the regular page; the on-screen Exit button remains available.'},{title:'Use it as an idle display',text:'Keep the animation on a spare monitor when you want something simple in the background. It does not replace your device’s power-saving settings. Choose the [[/clock-screensaver/|clock]] if you prefer a useful, still display.'}],note:'Moving content is not a guarantee against image retention or burn-in. Follow your display manufacturer’s recommendations for idle use.',guide:'fullscreen-and-shortcuts'},
  {slug:'focus-timer',name:'Focus timer',color:'#E3EACF',category:'savers',kind:'timer',description:'One task. A little breathing room. Set a quiet countdown and give your work the screen.',intro:'Choose a session length and start a clear visual countdown. You can pause, resume, or reset the timer, then expand it to full screen. It is designed for a visible work session rather than critical reminders or background alarms.',uses:[{title:'Set a manageable session',text:'Choose 5, 15, 25, or 50 minutes, or enter your own duration. Decide on one concrete task before pressing Start. The tool does not prescribe an ideal work interval; choose a length that fits the work and your comfort.'},{title:'Pause without losing your place',text:'Pause the countdown when you need to step away. Resuming continues from the remaining time. Reset returns the timer to the selected session length, and changing the duration prepares a new session.'},{title:'Keep the end in view',text:'The countdown uses elapsed time, so a delayed browser tick is corrected on the next update. Browsers can still suspend tabs or close pages. Keep the tab visible and use a dedicated alarm for anything time-critical.'}],note:'There are no notification permissions, sounds, task tracking, or cloud storage. Reloading the page resets the session. For a plain desk display, try the [[/clock-screensaver/|clock screensaver]].',guide:'fullscreen-and-shortcuts'},
  {slug:'matrix-screensaver',name:'Digital rain',color:'#111B16',category:'savers',kind:'rain',description:'A quiet stream of green characters. An atmospheric screensaver, entirely in your browser.',intro:'Digital rain is a decorative animation of falling characters on a dark background. It is a visual effect only: the symbols do not represent commands, network activity, or access to another computer. Pause it or adjust its pace to suit your space.',uses:[{title:'Control the movement',text:'Use the speed control to choose a slower or faster fall. The page starts paused for visitors who request reduced motion in their device settings, and the Pause control is always available.'},{title:'Create a visual backdrop',text:'Use the animation on a spare screen for a creative set or desk scene. Check for reflections and rolling bands in a camera preview if you plan to photograph a display; camera settings and refresh behavior affect the result.'},{title:'Keep an easy exit',text:'The full screen view includes an Exit control and supports Escape. No keyboard input is sent to a server, and the animation never asks for passwords or device permissions.'}],note:'If you want a still background, choose a [[/green-screen/|green screen]] or [[/black-screen/|black screen]]. This effect does not perform computer diagnostics or security operations.',guide:'fullscreen-and-shortcuts'},
  {slug:'fake-update-screen',name:'Update screen demo',color:'#1B3156',category:'extras',kind:'update',description:'A fictional update screen for demos and creative sets. Clearly labeled, easy to exit.',intro:'Build a generic progress-screen simulation with an adjustable percentage. The design is fictional and keeps a visible Demo label. It never downloads an update, changes settings, or blocks you from leaving the page.',uses:[{title:'Set the progress',text:'Move the percentage slider to control the visual progress. Pause the animation for a still frame or let it advance slowly. The number is part of the simulation and has no connection to a real update process.'},{title:'Use it in an agreed demonstration',text:'Show a fictional waiting state in a presentation, a video set, or a product sketch. Explain what it is to anyone using the device, and avoid presenting it as a real system or security message.'},{title:'Leave at any time',text:'Press Escape or use the visible Exit button. The browser remains in control of full screen mode. For a useful waiting display instead, open the [[/clock-screensaver/|clock]] or [[/focus-timer/|focus timer]].'}],note:'This page is labeled as a simulation in both the preview and full screen view. No system brand, security alert, or genuine device update is implied.',guide:'fullscreen-and-shortcuts'},
  {slug:'broken-screen',name:'Cracked screen demo',color:'#23302B',category:'extras',kind:'crack',description:'A stylized cracked-glass effect for a creative backdrop. Your actual display stays untouched.',intro:'This decorative screen draws a fictional cracked-glass pattern over a dark canvas. Adjust its intensity for a visual effect in a sketch, presentation, or creative scene. A visible Simulation label makes its purpose clear.',uses:[{title:'Choose the visual intensity',text:'Use the intensity slider to fade the crack lines in or out. The drawing is generated by the page and does not describe the condition of your device. It does not access hardware sensors.'},{title:'Use it with permission',text:'Keep the effect to a device you own or have permission to use. It should be a clearly understood visual demonstration, not a way to make someone believe expensive equipment has been damaged.'},{title:'Return to a normal canvas',text:'Exit full screen at any time with Escape or the Exit control. If you are trying to inspect a genuinely damaged display, use the [[/monitor-test/|monitor patterns]] and consult an appropriate repair service.'}],note:'The pattern is an illustration. It cannot crack glass, repair glass, diagnose damage, or change your files.',guide:'fullscreen-and-shortcuts'},
];
tools.push(...extras);

export const guides = [
  {slug:'use-a-white-screen',title:'Practical ways to use a white screen',description:'Use a plain white background for fill light, creative work, and a more controlled display check.',category:'EVERYDAY TOOLS',minutes:5,color:'#E6EDD9',related:['white-screen','custom-color-screen','dead-pixel-test'],sections:[
    {title:'Start with one simple purpose',paragraphs:['A white screen is useful because there is so little in it. Without wallpaper, menus, or a photograph competing for attention, your display becomes a repeatable visual surface. That does not turn it into specialist equipment, but it can solve a small problem with very little setup.','Open the [[/white-screen/|white screen tool]] and decide whether you need light, a background image, or a pattern to inspect. Those uses call for slightly different settings. Full screen mode removes the page furniture; the PNG download creates a file rather than a screenshot of the website.']},
    {title:'Use your display as a modest fill light',paragraphs:['For a video call, put the bright area near your camera and face the main light in the room. Begin with low brightness and raise it while watching the preview in your calling app. If a window behind you is much brighter than your face, moving your seat often helps more than making the display brighter.','A white screen can soften shadows nearby, especially on a large display. It cannot promise a particular exposure or color temperature. If the light looks too cool in a warm room, try the [[/zoom-light/|adjustable call light]] and choose a gently warmer tone. Avoid assuming that a setting comfortable to your eyes will look identical on camera.']},
    {title:'Prepare a clean visual check',paragraphs:['A uniform white field can reveal dark points, dust, and obvious uneven patches. Remove surface dust according to your manufacturer’s guidance first, then inspect the screen from your usual position. Do not press on a suspicious area.','Compare the same spot against black and the primary colors. The [[/dead-pixel-test/|manual pixel test]] keeps those backgrounds together. A visible mark is evidence to investigate, not an automatic diagnosis; reflections, dirt, and panel defects can look similar at a glance.']},
    {title:'Make a background file instead of a screenshot',paragraphs:['Choose the dimensions used by your slide, social graphic, or video project, then download the PNG. The exported file contains only the background. Browser controls, tool labels, and the rest of this page are not included.','Keep the brightness slider at 100% if you want the export to remain pure white. Visual dimming is applied to the file too. For an exact off-white, use the [[/custom-color-screen/|custom color tool]] and enter the shade directly.']},
    {title:'Keep the limits in mind',paragraphs:['The website cannot change your monitor’s hardware brightness, calibrate its colors, or measure its light output. Your device and room still determine what the white surface looks like. Use a comfortable brightness rather than treating maximum output as a goal.','For tracing, avoid resting heavy objects on a display or applying pressure through paper. For screen cleaning, switch off and follow the manufacturer’s instructions before wiping. A useful browser tool should support a task without being mistaken for a dedicated lightbox or repair instrument.']},
  ]},
  {slug:'check-your-monitor',title:'How to give your monitor a useful visual check',description:'A repeatable checklist for flat colors, grayscale steps, gradients, and common look-alike marks.',category:'DISPLAY BASICS',minutes:6,color:'#DCE5F1',related:['dead-pixel-test','monitor-test','gray-screen'],sections:[
    {title:'Prepare the display and the room',paragraphs:['Set your display to its native resolution and use a comfortable, repeatable hardware brightness. Disable automatic brightness or scheduled color changes temporarily if they would change during the comparison. Sit directly in front of the panel, and note the room lighting.','Remove dust using the manufacturer’s recommended method. Surface particles can look surprisingly similar to a dark pixel. Avoid pressing on the screen, using improvised solvents, or treating a visual browser test as a repair routine.']},
    {title:'Move through flat backgrounds',paragraphs:['Open the [[/dead-pixel-test/|dead pixel test]] in full screen and work through white, black, red, green, and blue. Scan the panel in sections so you do not lose your place. Pause on each field long enough to inspect it comfortably; a fast flashing pattern is unnecessary.','If a point looks unusual, compare its exact position across all colors. A dark point that appears only on one background may have a different explanation from a bright point visible on black. A browser cannot label the hardware condition reliably, so record what you see rather than relying on an automatic verdict.']},
    {title:'Look at grayscale and gradients',paragraphs:['The [[/monitor-test/|monitor test]] includes a grayscale ramp and separate dark and light steps. Look for obvious bands in the ramp and whether adjacent steps remain distinguishable. Do this from your normal viewing position instead of moving close to the panel until every imperfection dominates the image.','A stepped-looking gradient can come from multiple parts of the display pipeline. Panel settings, output depth, browser rendering, and the signal path can all matter. This pattern is a starting point for comparison; it does not measure bit depth, professional color accuracy, HDR performance, or response time.']},
    {title:'Separate reflections from panel behavior',paragraphs:['Use the [[/black-screen/|black background]] in a dim room, then change your position slightly. A reflection often changes with the room and viewing angle. A mark tied to a particular panel location tends to remain there, though its visibility may change.','Large differences near the edges can depend on panel technology and viewing angle. A single phone photograph may exaggerate or hide them because the camera selects its own exposure. Describe the conditions in which you can see an issue, and keep any photos consistent if you contact support.']},
    {title:'Turn the observation into a useful next step',paragraphs:['Write down the background color, approximate position, brightness setting, and whether the point remains visible on different fields. If you have another cable or input source available, comparing them may help isolate a signal-related problem. Avoid drawing conclusions from one field alone.','Consult the manufacturer’s warranty and support guidance for a suspected hardware fault. Pixel policies differ, and this site does not decide warranty eligibility. For color-critical work, use the appropriate measurement equipment and a color-managed workflow rather than relying on a visual test page.']},
  ]},
  {slug:'better-video-call-lighting',title:'Better video call lighting with a spare screen',description:'Position your screen, balance the room, and choose a useful tone without switching on a webcam here.',category:'CREATIVE SETUPS',minutes:5,color:'#F7E4CF',related:['zoom-light','ring-light','white-screen'],sections:[
    {title:'Fix the direction before the brightness',paragraphs:['Light coming from in front of you is usually easier to work with than a bright window behind you. Before opening a tool, look at where the room’s main light comes from. Turn your desk or seat toward it when that is practical.','Place a spare display near the camera and open the [[/zoom-light/|video call light]]. A small change in height or angle can soften a shadow more effectively than pushing the brightness slider to its maximum. Keep your camera preview open in the application you actually use for calls.']},
    {title:'Bring up the fill gradually',paragraphs:['Start with a neutral white field at low visual brightness. Increase it until your face is easier to see without becoming washed out. If the result still looks dark, check whether the camera is exposing for a bright background rather than your face.','Screen size, distance, hardware brightness, and room light affect the result. This page only changes the pixels it displays; it cannot adjust your panel’s backlight or tell you how much light reaches your face. A browser slider therefore represents visual dimming, not a calibrated light level.']},
    {title:'Match the tone to the room',paragraphs:['A cool display can look different beside warm ceiling lamps. Use a slightly warmer tone if it looks more natural in your preview. Make one change at a time so it is clear what improved the result.','Avoid strongly colored screens if you want neutral skin tones or accurate product colors. A [[/yellow-screen/|yellow background]] or other saturated color can be useful creatively, but it may introduce an obvious tint rather than a subtle improvement.']},
    {title:'Try a ring, then compare it fairly',paragraphs:['The [[/ring-light/|ring light tool]] uses a dark center and a bright border. Adjust its width and compare it against the full-panel light at the same hardware brightness. The pattern changes the bright area and the reflections; it is not a virtual copy of a dedicated photographic ring light.','If you wear glasses, move the screen slightly to reduce bright reflections in the lenses. Check whether a smaller ring or a different angle works better. A softer result is often about where the light sits rather than a single perfect setting.']},
    {title:'Keep the setup simple and private',paragraphs:['These tools display color and do not request access to your camera or microphone. Judge the result in your meeting app rather than expecting this page to analyze your appearance. You can use a second monitor for lighting while keeping meeting controls on the first.','Use Escape or the on-screen Exit control to leave full screen. If the browser does not support full screen, the expanded page view still provides a larger light surface. Close the tool when you are finished; it does not need to run in the background.']},
  ]},
  {slug:'choose-a-background-size',title:'Choose the right size for a background PNG',description:'Understand pixel dimensions, aspect ratios, portrait exports, and the difference between a file and a screenshot.',category:'CREATIVE WORKFLOW',minutes:4,color:'#E8DEF4',related:['custom-color-screen','gradient-screen','white-screen'],sections:[
    {title:'Start with the destination',paragraphs:['Choose dimensions that match the canvas in your editor. A 1920 × 1080 background fits a Full HD landscape video. A 1080 × 1920 background fits a portrait composition, while 1080 × 1080 is a square. The right choice is the size of your project, not necessarily the resolution of the monitor you are using.','The [[/custom-color-screen/|custom background generator]] provides common presets and separate width and height fields. Changing a field switches the preset to Custom so the interface does not claim that your edited dimensions are still a standard size.']},
    {title:'Keep the aspect ratio intentional',paragraphs:['Aspect ratio is the relationship between width and height. A landscape 16:9 image and a portrait 9:16 image contain the same kinds of pixels but fit very different compositions. Cropping a background may be harmless for one solid color, but a gradient can change its apparent placement when cropped.','For a [[/gradient-screen/|gradient PNG]], set the final dimensions before exporting so the generated blend fits the destination without stretching it later. The on-page canvas fits your device; the exported image uses the dimensions you entered.']},
    {title:'Know what the download contains',paragraphs:['The download is a generated PNG containing the background alone. It is not a screenshot, so it excludes browser chrome, interface labels, and the surrounding website. Solid colors and gradients use an opaque background rather than transparency.','The visual brightness setting is included in the export. Keep it at 100% for the unmodified selected color, or use the color field to choose a deliberate darker shade. You can open the image in your editor to verify its pixel dimensions.']},
    {title:'Use a sensible resolution',paragraphs:['This project limits each edge to 4,096 pixels and rejects invalid or zero dimensions. Large canvases need more browser memory even when their final compressed file is small. If an export fails on a low-memory device, reduce the dimensions and try again.','Increasing the size of a solid color does not reveal extra detail, but matching the destination avoids an unnecessary resize in your workflow. PNG uses lossless compression; color appearance can still vary with display profiles and the application viewing the file.']},
    {title:'Keep filenames easy to reuse',paragraphs:['Downloads use a descriptive tool name, dimensions, and file extension. Save the image alongside your project assets and rename it if your team uses a particular naming convention. The generated file contains no advertising, site controls, or hidden tracking code.','If you only need to show a color while presenting, use full screen instead of downloading a file. The [[/guides/fullscreen-and-shortcuts/|full screen guide]] explains the controls and what to do when a browser does not offer a native full screen mode.']},
  ]},
  {slug:'fullscreen-and-shortcuts',title:'Full screen controls, shortcuts, and browser limits',description:'Learn the keyboard controls, how to exit, and why full screen behavior varies between browsers.',category:'GETTING STARTED',minutes:4,color:'#D9E8E3',related:['white-screen','clock-screensaver','focus-timer'],sections:[
    {title:'Enter full screen with an explicit action',paragraphs:['Click the preview or use the Full screen button. On a desktop keyboard, F toggles full screen when you are not typing in a field. The browser normally requires a user action before it will let a page enter this mode.','Full screen gives the canvas the display area and hides the tool controls. A small exit control remains available. The surrounding website, related links, and any future advertising stay outside the canvas.']},
    {title:'Leave whenever you need to',paragraphs:['Press Escape or choose Exit in the expanded canvas. Changing tabs or switching applications may also leave native full screen. This site does not try to block the browser’s own escape behavior.','When native full screen is unavailable or rejected, the tool uses an expanded view within the page. Browser bars may remain visible. The exit control and Escape still close that view, so you do not need to reload the page to recover the normal layout.']},
    {title:'Use tool-specific keys carefully',paragraphs:['On the [[/dead-pixel-test/|dead pixel test]], Left and Right move between colors and Space advances while the canvas is expanded. These shortcuts are ignored when you are typing into an input, selecting an option, or editing text.','Other tools use their labeled controls to avoid surprises. The [[/focus-timer/|focus timer]] has explicit Start, Pause, and Reset buttons. Animated screensavers provide a visible pause button and begin paused when your device requests reduced motion.']},
    {title:'Understand the optional awake control',paragraphs:['Keep screen awake requests the browser’s Screen Wake Lock feature where it is supported. A successful request can help keep the visible page active, but the browser or operating system can release it. The status beside the control reflects whether a lock is currently active.','A hidden tab does not keep a useful visible screen running. If you return to the page with the option still selected, the tool can request the lock again. This is a convenience feature rather than a replacement for your device’s power settings.']},
    {title:'Treat the display as a browser tool',paragraphs:['Full screen does not lock your computer, change your hardware brightness, or give the website control of other monitors. Move the browser window to the display you want to use, then enter full screen there.','Use your operating system for device security and important alarms. The [[/clock-screensaver/|clock]] reads your device’s local time, while the timer is a visual work aid that resets on reload. Those limits keep the tools straightforward and predictable.']},
  ]},
];

export const getTool = (slug) => tools.find(t => t.slug === slug);
export const getCategory = (id) => categories.find(c => c.id === id);
export const getGuide = (slug) => guides.find(g => g.slug === slug);
export const toolFaqs = (tool) => {
  if (tool.category==='colors' || tool.kind==='gradient') return [
    ['How do I open and close full screen?', 'Click the canvas or the Full screen button. On desktop you can also press F when you are not typing in a field. Press Escape or use Exit to return. If native full screen is unavailable, the tool opens an expanded page view.'],
    ['Does the brightness slider change my monitor settings?', 'No. It visually dims the canvas by adding black over the selected color. Adjust your device’s own display settings if you need to change its physical brightness. Dimming is also included in PNG exports.'],
    ['Can I download this background?', 'Yes. Choose a size or enter dimensions from 1 to 4,096 pixels per edge, then select Download PNG. The file contains only the background, without website controls.'],
    ['Does this page use my camera or upload my colors?', 'No. The screen and image generator run locally in your browser. They do not request camera or microphone access, and selected colors are not sent to a tool server. See the privacy policy for hosting and optional advertising details.'],
  ];
  return [
    ['Does this tool need an account or installation?', 'No. Open the page in a modern browser and use the controls. No account, extension, or software download is required.'],
    ['How do I exit the expanded screen?', 'Press Escape or use the visible Exit button. If the browser cannot enter native full screen, an expanded page view provides the same easy exit.'],
    ['Does the tool control my device?', 'No. It displays patterns, animations, or a timer inside a browser tab. It does not change hardware settings, install updates, diagnose a panel automatically, or lock your computer.'],
    ['Why might the screen not stay awake?', 'Screen Wake Lock support and permission vary. The browser or operating system can release a lock, particularly when a tab is hidden. Check the control’s status and use device power settings when needed.'],
  ];
};
